octo.registerCommand("note-stats", "Word count, reading time and outline", function (t) {
  var text = String(t);
  var body = text.replace(/^---\r?\n[\s\S]*?\r?\n---[ \t]*\r?\n?/, "");
  var stripped = body.replace(/`{1,3}[^`]*`{1,3}/g, " ").replace(/[#>*_\[\]()!|]/g, " ");
  var parts = stripped.split(/\s+/), n = 0;
  for (var i = 0; i < parts.length; i++) if (parts[i].replace(/^\s+|\s+$/g, "").length) n++;
  var mins = Math.ceil(n / 200);
  if (mins < 1) mins = 1;
  var lines = body.split("\n"), heads = [];
  for (var j = 0; j < lines.length; j++) {
    var h = lines[j].match(/^(#{1,6})[ \t]+(.+)$/);
    if (h) heads.push(new Array(h[1].length).join("  ") + "- " + h[2].replace(/^\s+|\s+$/g, ""));
  }
  var out = ["> [!info] Note stats",
             "> " + n + " words · " + body.length + " characters · ~" + mins + " min read"];
  if (heads.length) {
    out.push(">");
    out.push("> **Outline**");
    for (var k = 0; k < heads.length; k++) out.push("> " + heads[k]);
  }
  return out.join("\n") + "\n\n" + text;
});
